"use strict";(globalThis.webpackChunk_8x8_developer_docs=globalThis.webpackChunk_8x8_developer_docs||[]).push([[14206],{69351:e=>{e.exports=JSON.parse('{"id":"2026-10-16-whatsapp-button-reply-webhook-fields","date":"2026-10-16","products":["Connect"],"product":"Connect","channel":"WhatsApp","changeType":"Changed","title":"Button replies in the inbound Messaging Apps webhook clarified","excerpt":"The inbound Messaging Apps webhook(/connect/docs/inbound-chatapps-message) page now explains how to tell which WhatsApp button a customer tapped, with sample payloads for both kinds of button.","hasArticle":true,"bodyHtml":"<p>The <a href=\\"/connect/docs/inbound-chatapps-message\\">inbound Messaging Apps webhook</a> page now explains how to tell which WhatsApp button a customer tapped, with sample payloads for both kinds of button.</p>\\n<ul>\\n<li><strong>Reply buttons on interactive messages:</strong> the <code>id</code> you set on each button (<code>action.buttons[].reply.id</code>) comes back in <code>content.interactive.button_reply.id</code>.</li>\\n<li><strong>Quick-reply buttons on template messages:</strong> the message arrives with type <code>Buttons</code>. The <code>payload</code> parameter you set for that button when sending the template comes back in <code>content.payload</code>, and the button label is in <code>content.text</code>.</li>\\n<li><strong><code>replyToUmid</code></strong> is the UMID of the message you sent that the customer replied to. It was previously described as referring to an earlier inbound message. Use it to link a button tap back to the original send or campaign.</li>\\n</ul>\\n<p>No webhook fields changed. This is a documentation correction only.</p>\\n"}')}}]);